// Oracle stub: only the value import radius-relay.ts uses. The constant is
// copied verbatim from upstream packages/protocol/src/framing.rs
// (DEFAULT_MAX_FRAME_LENGTH = 16 * 1024 * 1024).
export const DEFAULT_MAX_FRAME_LENGTH = 16 * 1024 * 1024;
export function isServerId(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/u.test(String(value));
}
